A quantity is called a generalized divergence \cite{PV10,SW12} if it satisfies the following monotonicity (data-processing) inequality for all density operators $\rho$ and $\sigma$ and quantum channels $\mc{N}$:
\begin{equation}\label{eq:gen-div-mono}
\mathbf{D}(\rho\Vert \sigma)\geq \mathbf{D}(\mathcal{N}(\rho)\Vert \mc{N}(\sigma)).
\end{equation}
Examples include the quantum relative entropy~\cite{Ume62} 
\begin{equation}
D(\rho\Vert\sigma)\coloneqq \Tr[\rho\log_2(\rho-\sigma)],
\end{equation}
for $\supp(\rho)\subseteq \supp(\sigma)$, otherwise it is $\infty$, as well as the sandwiched R\'enyi relative entropy  \cite{MDSFT13,WWY14} which is denoted as $\wt{D}_\alpha(\rho\Vert\sigma)$  and defined for states
$\rho,\sigma$, and  $\forall \alpha\in (0,1)\cup(1,\infty)$ as
\begin{equation}\label{eq:def_sre}
\wt{D}_\alpha(\rho\Vert \sigma):= \frac{1}{\alpha-1}\log_2 \Tr\left[\left(\sigma^{ (1-\alpha) / 2\alpha }\rho\sigma^{ (1-\alpha) / 2\alpha }\right)^\alpha \right] ,
\end{equation}
but it is set to $+\infty$ for $\alpha\in(1,\infty)$ if $\supp(\rho)\nsubseteq \supp(\sigma)$. In the limit $\alpha\to 1$ the sandwiched R\'enyi relative entropy converges to the quantum relative entropy, in the limit  $\alpha\to \infty$, it converges to the max-relative entropy \cite{MDSFT13}, which is defined as \cite{D09,Dat09}
\begin{equation}\label{eq:max-rel}
D_{\max}(\rho\Vert\sigma)\coloneqq \inf\{\lambda\in\mathbb{R}:\ \rho \leq 2^\lambda\sigma\},
\end{equation}
and if $\supp(\rho)\nsubseteq\supp(\sigma)$ then $D_{\max}(\rho\Vert\sigma)=\infty$. Another generalized divergence  is the $\varepsilon$-hypothesis-testing divergence \cite{BD10,WR12},  defined as
\begin{equation}
D^\varepsilon_h\!\(\rho\Vert\sigma\):=-\log_2\inf_{\Lambda: 0\leq\Lambda\leq \bbm{1}}\{\Tr[\Lambda\sigma]:\  \Tr[\Lambda\rho]\geq 1-\varepsilon\},
\end{equation}
for $\varepsilon\in[0,1]$ and density operators $\rho,\sigma$. For a more detailed description and other examples of the generalized divergences like the trace distance $\norm{\rho-\sigma}_{1}$ and negative of fidelity $-F(\rho,\sigma)$ and their properties, see Appendix \ref{App:Div}.

A quantity is called a generalized divergence \cite{PV10,SW12} if it satisfies the following monotonicity (data-processing) inequality for all density operators $\rho$ and $\sigma$ and quantum channels $\mc{N}$:
\begin{equation}\label{eq:gen-div-mono}
\mathbf{D}(\rho\Vert \sigma)\geq \mathbf{D}(\mathcal{N}(\rho)\Vert \mc{N}(\sigma)).
\end{equation}
As a direct consequence of the above inequality, any generalized divergence satisfies the following two properties for an isometry $U$ and a state~$\tau$ \cite{WWY14}:
\begin{align}
\mathbf{D}(\rho\Vert \sigma) & = \mathbf{D}(U\rho U^\dag\Vert U \sigma U^\dag),\label{eq:gen-div-unitary}\\
\mathbf{D}(\rho\Vert \sigma) & = \mathbf{D}(\rho \otimes \tau \Vert \sigma \otimes \tau).\label{eq:gen-div-prod}
\end{align}

\begin{theorem}\label{thm:emax-key-converse} For a fixed $n,\ K\in\mathbb{N},\ \varepsilon\in(0,1)$, the following bound holds for an $(n,K,\varepsilon)$ protocol for LOCC-assisted secret key agreement over a multiplex $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$: 
\begin{equation}\label{eq:emax-key-converse} 
\frac{1}{n}\log_2K\leq E_{\max,E}(\mc{N})+ \frac{1}{n}\log_2\left(\frac{1}{1-\varepsilon}\right), 
\end{equation} 
where the max-relative entropy of entanglement $E_{\max,\E}(\mc{N})$ of the multiplex channel $\mc{N}$ is 
\begin{equation*} 
E_{\max,\E}(\mc{N}) \coloneqq \sup_{\psi\in\FS(:\vv{LA'}:\vv{RB}:)}\inf_{\sigma\in\FS(:\vv{LA}:\vv{R}:\vv{C}:)} D_{\max}(\mc{N}(\psi)\Vert\sigma)
\end{equation*} 
and it suffices to optimize over pure states $\psi$.
\end{theorem}
