Let $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ be a multipartite 
quantum channel that is tele-covariant with respect to groups $\{\msc{G}_a\}_{a\in\msc{A}}$ and $\{\msc{G}_b\}_{b\in\msc{B}}$ as defined in Section~\ref{sec:tele-cov}.
By definition, for all $a\in\msc{A}$ and $b\in\msc{B}$, we have
\begin{align}
&\frac{1}{G_a}\sum_{g_a}\mathcal{U}_{A''_a}^{g_a}(\Phi^+_{A''_aL_a})=\frac{\bbm{1}_{A''_a}}{|A''_a|}\otimes\frac{\bbm{1}_{L_a}}{|L_a|},\label{eq:max-ent-cov-action_A}\\
&\frac{1}{G_b}\sum_{g_b}\mathcal{U}_{B'_b}^{g_b}(\Phi^+_{B'_bR_b})=\frac{\bbm{1}_{B'_b}}{|B'_b|}\otimes\frac{\bbm{1}_{R_b}}{|R_b|},\label{eq:max-ent-cov-action_B}
\end{align}
respectively, where $A''_a\simeq L_a$, $B'_b\simeq R_b$ and $\Phi^+$ denotes an EPR state. Note that in order for each $\{U_{A''_a}^{g_a}\}$ and $\{U_{B'_b}^{g_b}\}$ to be one-designs, it is necessary that $\left\vert A''_a\right\vert ^{2}\leq G_a $ and $\left\vert B'_b\right\vert ^{2}\leq G_b $ \cite{AMTW00}.

For every $a\in\msc{A}$ and every $b\in\msc{B}$, we can now define $\{E_{A''_aL_a}^{g_a}\}_{g_a}$ and $\{E_{B_b'R_b}^{g_b}\}_{g_b}$,
with respective elements defined as
\begin{align}
&E_{A''_aL_a}^{g_a}:=\frac{\left\vert A'_a\right\vert
^{2}}{G_a }U_{A''_a}^{g_a}\Phi^+_{A''_aL_a}\left(  U_{A''_a}^{g_a}\right)  ^{\dag},\\
&E_{B'_bR_b}^{g_b}:=\frac{\left\vert B_b\right\vert
^{2}}{G_b }U_{B'_b}^{g_b}\Phi^+_{B'_bR_b}\left(  U_{B'_b}^{g_b}\right)  ^{\dag},
\end{align}
where $A'_a\simeq A''_a$ and $B_b\simeq B'_b$. It follows from the fact that $\left\vert A'_a\right\vert ^{2}
\leq G_a$ and $\left\vert B_b\right\vert ^{2}
\leq G_b$ as well as  \eqref{eq:max-ent-cov-action_A} and \eqref{eq:max-ent-cov-action_B} that
$\{E_{A''_aL_a}^{g_a}\}_{g_a}$ and $\{E_{B_b'R_b}^{g_b}\}_{g_b}$ are valid POVMs for all $a\in\msc{A}$ and $b\in\msc{B}$.


The simulation of the channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ via teleportation begins with a state $\rho_{\vv{A''}\vv{B'}}$ and a shared resource $\theta_{\vv{LA}\vv{R}\vv{C}}=\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}\(\Phi^+_{\vv{L}\vv{R}|\vv{A'}\vv{B}}\)$. The desired outcome is for the receivers to receive
the state $\mathcal{N}(\rho_{\vv{A''}\vv{B'}})$ and for the protocol to work independently of the input state
$\rho_{\vv{A''}\vv{B'}}$. The first step is for senders $\tf{A}_a$ and $\tf{B}_b$ to locally
perform the measurement $\left\{\bigotimes_{a\in\msc{A}}E_{A''_aL_a}^{g_a}\otimes\bigotimes_{b\in\msc{B}}E_{B_b'R_b}^{g_b}\right\}_{\vv{g}}$ and then send the outcomes $\vv{g}$ to the
receivers. Based on the outcomes $\vv{g}$, the receivers $\tf{A}_a$ and $\tf{C}_c$ then perform
$W_{A_a}^{\vv{g}}$ and $W_{C_c}^{\vv{g}}$, respectively. The following analysis demonstrates that this
protocol works, by simplifying the form of the post-measurement state:

\begin{widetext}
\begin{align}
&  \left(\prod_{a\in\msc{A}}G_a\prod_{b\in\msc{B}}G_b\right) \Tr_{\vv{A''L}\vv{B'R}}\left[\left(\bigotimes_{a\in\msc{A}}E_{A''_aL_a}^{g_a}\otimes\bigotimes_{b\in\msc{B}}E_{B_b'R_b}^{g_b}\right)(\rho_{\vv{A"}\vv{B'}}\otimes\theta_{\vv{LA}\vv{R}\vv{C}})\right]\nonumber\\

&  =\left(\prod_{a\in\msc{A}}\left\vert A'_a\right\vert ^{2} \prod_{b\in\msc{B}}\left\vert B_b\right\vert ^{2}\right)\Tr_{\vv{A''L}\vv{B'R}}\left[\left(\bigotimes_{a\in\msc{A}}{U}_{A''_a}^{g_a}\Phi^+_{A''_aL_a}{{U}_{A''_a}^{g_a}}^\dag\otimes\bigotimes_{b\in\msc{B}}{U}_{B_b'}^{g_b}\Phi^+_{B_b'R_b}{{U}_{B_b'}^{g_b}}^\dag\right)(\rho_{\vv{A"}\vv{B'}}\otimes\theta_{\vv{LA}\vv{R}\vv{C}})\right]\\

&  =\left(\prod_{a\in\msc{A}}\left\vert A'_a\right\vert ^{2} \prod_{b\in\msc{B}}\left\vert B_b\right\vert ^{2}\right)\bra{\Phi^+}_{\vv{A''}\vv{B'}|\vv{L}\vv{R}}\left( \bigotimes_{a\in\msc{A}} U_{A''_a}^{g_a}\otimes \bigotimes_{b\in\msc{B}} U_{B_b'}^{g_b}\right) ^{\dag}\rho_{\vv{A"}\vv{B'}}\otimes\theta_{\vv{LA}\vv{R}\vv{C}}\left( \bigotimes_{a\in\msc{A}} U_{A''_a}^{g_a}\otimes \bigotimes_{b\in\msc{B}} U_{B_b'}^{g_b}\right)\ket{\Phi^+}_{\vv{A''}\vv{B'}|\vv{L}\vv{R}}\\

&  =\left(\prod_{a\in\msc{A}}\left\vert A'_a\right\vert ^{2} \prod_{b\in\msc{B}}\left\vert B_b\right\vert ^{2}\right)\bra{\Phi^+}_{\vv{A''}\vv{B'}|\vv{L}\vv{R}}\left( \bigotimes_{a\in\msc{A}} U_{A''_a}^{g_a}\otimes \bigotimes_{b\in\msc{B}} U_{B_b'}^{g_b}\right) ^{\dag}\rho_{\vv{A"}\vv{B'}}\left( \bigotimes_{a\in\msc{A}} U_{A''_a}^{g_a}\otimes \bigotimes_{b\in\msc{B}} U_{B_b'}^{g_b}\right)\otimes\theta_{\vv{LA}\vv{R}\vv{C}}\ket{\Phi^+}_{\vv{A''}\vv{B'}|\vv{L}\vv{R}}\\

&  =\left(\prod_{a\in\msc{A}}\left\vert A'_a\right\vert ^{2} \prod_{b\in\msc{B}}\left\vert B_b\right\vert ^{2}\right)\bra{\Phi^+}_{\vv{A''}\vv{B'}|\vv{L}\vv{R}}\left[\left( \bigotimes_{a\in\msc{A}} U_{L_a}^{g_a}\otimes \bigotimes_{b\in\msc{B}} U_{R_b}^{g_b}\right) ^{\dag}\rho_{\vv{L}\vv{R}}\left( \bigotimes_{a\in\msc{A}} U_{L_a}^{g_a}\otimes \bigotimes_{b\in\msc{B}} U_{R_b}^{g_b}\right)\right]^\ast\theta_{\vv{LA}\vv{R}\vv{C}}\ket{\Phi^+}_{\vv{A''}\vv{B'}|\vv{L}\vv{R}}
.\label{eq:cov-tp-simul-block-1}
\end{align}
\end{widetext}
The first three equalities follow by substitution and some rewriting. The
fourth equality follows from the fact that

\begin{equation}
\langle\Phi|_{A^{\prime}A}M_{A^{\prime}}=\langle\Phi|_{A^{\prime}A}M_{A}
^{\ast}\label{eq:ricochet-prop}
\end{equation}
for any operator $M$ and where $\ast$ denotes the complex conjugate, taken
with respect to the basis in which $\ket{\Phi}_{A^{\prime}A}$ is defined. 
Continuing, we have that

\begin{widetext}
\begin{align}
\text{Eq.~}\eqref{eq:cov-tp-simul-block-1} & =\left(\prod_{a\in\msc{A}}\left\vert A'_a\right\vert  \prod_{b\in\msc{B}}\left\vert B_b\right\vert \right)\Tr_{\vv{L}\vv{R}}\left[\left[\left( \bigotimes_{a\in\msc{A}} U_{L_a}^{g_a}\otimes \bigotimes_{b\in\msc{B}} U_{R_b}^{g_b}\right) ^{\dag}\rho_{\vv{L}\vv{R}}\left( \bigotimes_{a\in\msc{A}} U_{L_a}^{g_a}\otimes \bigotimes_{b\in\msc{B}} U_{R_b}^{g_b}\right)\right]^\ast\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}\(\Phi^+_{\vv{L}\vv{R}|\vv{A'}\vv{B}}\)\right]\\

& =\left(\prod_{a\in\msc{A}}\left\vert A'_a\right\vert  \prod_{b\in\msc{B}}\left\vert B_b\right\vert\right)\Tr_{\vv{L}\vv{R}}\left[\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}\left(\left( \bigotimes_{a\in\msc{A}} U_{{A'}_a}^{g_a}\otimes \bigotimes_{b\in\msc{B}} U_{{B}_b}^{g_b}\right) ^{\dag}\rho_{\vv{{A'}}\vv{{B}}}\left( \bigotimes_{a\in\msc{A}} U_{{A'}_a}^{g_a}\otimes \bigotimes_{b\in\msc{B}} U_{{B}_b}^{g_b}\right)\Phi^+_{\vv{L}\vv{R}|\vv{A'}\vv{B}}\right)\right]\\

&= \mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}\left(\left( \bigotimes_{a\in\msc{A}} U_{{A'}_a}^{g_a}\otimes \bigotimes_{b\in\msc{B}} U_{{B}_b}^{g_b}\right) ^{\dag}\rho_{\vv{{A'}}\vv{{B}}}\left( \bigotimes_{a\in\msc{A}} U_{{A'}_a}^{g_a}\otimes \bigotimes_{b\in\msc{B}} U_{{B}_b}^{g_b}\right)\right)\\

&=\(\bigotimes_{a\in\msc{A}}{W}_{A_a}^{\vv{g}}\otimes\bigotimes_{c\in\msc{C}}{W}_{C_c}^{\vv{g}}\)^\dag\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{A'}\vv{B}})\(\bigotimes_{a\in\msc{A}}{W}_{A_a}^{\vv{g}}\otimes\bigotimes_{c\in\msc{C}}{W}_{C_c}^{\vv{g}}\).
